/**
 * A removed member cannot keep owning live work; every non-archived issue
 * assigned to them is unassigned, one `issue.unassigned` per issue with the
 * remover as actor. Archived issues are left untouched.
 */
async function unassignLiveIssuesForRemovedMember(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  let cursor: string | null = null;

  do {
    const page = await issueRepo.listIssues({
      orgId,
      assigneeId: userId,
      includeArchived: false,
      limit: 100,
      cursor,
    });

    for (const issue of page.items) {
      const after = await issueRepo.setIssueAssignee(orgId, issue.id, null);
      await emit("issue.unassigned", {
        ...actorEnvelope(actor),
        issueId: after.id,
        projectId: after.projectId,
        previousAssigneeId: userId,
      });
    }

    cursor = page.nextCursor;
  } while (cursor);
}

